  Lemma ak6a : forall x : word, in_rangesb x (vm_noaccess VMM) = true -> in_rangesb x (vm_maps VMM) = true.
  Proof.
    intros x Hx. rewrite ak_maps. rewrite ak_noacc in Hx.
